from taf.sbts.oam.coam.admin.utils import raise_value_error


class LTECCMUplink(object):
    def __init__(self, lncel_rdn, measurement_type, reporting_time_interval, reception_subframe,
                 exception_subframe, earfcn, root_seq_index=None, prach_cs=None, prach_hs_flag=None, phys_cell_id=None,
                 tdd_frame_conf=None, tdd_spec_subf_conf=None):
        self.parameters = {"lncel_rDN": lncel_rdn,
                           "params": {
                               "measurementType": self.validate_param('measurementType',
                                                                      measurement_type,
                                                                      validity_clause=(measurement_type in ['PucchAck',
                                                                                                            'Prach',
                                                                                                            'PucchCqi',
                                                                                                            'PuschHarqAck',
                                                                                                            'PucchAckFormat1bWithChannelSelection',
                                                                                                            'PucchAckFormat3',
                                                                                                            'PucchFormat3with16Bits',
                                                                                                            'PucchFormat3with16BitsNack',
                                                                                                            'NPuschFormat2',
                                                                                                            'NPrach'])),
                               "reportingTimeInterval": self.validate_param('reportingTimeInterval',
                                                                            reporting_time_interval,
                                                                            [1, 10]),
                               "receptionSubframe": self.validate_param('receptionSubframe',
                                                                        reception_subframe,
                                                                        [0, 1023]),
                               "expectionSubframe": self.validate_param('expectionSubframe',
                                                                        exception_subframe,
                                                                        [0, 1023]),
                               "earfcn": self.validate_param('earfcn',
                                                             earfcn,
                                                             [0, 262143]),
                               "rootSeqIndex": self.validate_param('rootSeqIndex',
                                                                   root_seq_index,
                                                                   [0, 837]),
                               "prachCS": self.validate_param('prachCS',
                                                              prach_cs,
                                                              [0, 15]),
                               "prachHsFlag": prach_hs_flag,
                               "phyCellId": self.validate_param('phyCellId',
                                                                phys_cell_id,
                                                                [0, 503]),
                               "tddFrameConf": self.validate_param('tddFrameConf',
                                                                   tdd_frame_conf,
                                                                   [1, 3]),
                               "tddSpecSubfConf": self.validate_param('tddSpecSubfConf',
                                                                      tdd_spec_subf_conf,
                                                                      [3, 9])}
                           }

    @classmethod
    def from_response_dict(cls, response_dict):
        lncel_rdn = response_dict['lncel_rDN']
        measurement_type = response_dict['params']['measurementType']
        reporting_time_interval = response_dict['params']['reportingTimeInterval']
        reception_subframe = response_dict['params']['receptionSubframe']
        exception_subframe = response_dict['params']['expectionSubframe']
        earfcn = response_dict['params']['earfcn']
        root_seq_index = response_dict['params']['rootSeqIndex'] if 'rootSeqIndex' in response_dict['params'] else None
        prach_cs = response_dict['params']['prachCS'] if 'prachCS' in response_dict['params'] else None
        prach_hs_flag = response_dict['params']['prachHsFlag'] if 'prachHsFlag' in response_dict['params'] else None
        phys_cell_id = response_dict['params']['physCellId'] if 'physCellId' in response_dict['params'] else None
        tdd_frame_conf = response_dict['params']['tddFrameConf'] if 'tddFrameConf' in response_dict['params'] else None
        tdd_spec_subf_conf = response_dict['params']['tddSpecSubfConf'] if 'tddSpecSubfConf' in response_dict['params'] else None

        return cls(lncel_rdn=lncel_rdn,
                   measurement_type=measurement_type,
                   reporting_time_interval=reporting_time_interval,
                   reception_subframe=reception_subframe,
                   exception_subframe=exception_subframe,
                   earfcn=earfcn,
                   root_seq_index=root_seq_index,
                   prach_cs=prach_cs,
                   prach_hs_flag=prach_hs_flag,
                   phys_cell_id=phys_cell_id,
                   tdd_frame_conf=tdd_frame_conf,
                   tdd_spec_subf_conf=tdd_spec_subf_conf)

    def as_dict(self):
        attributes = self.parameters
        attributes['params'] = self.filter_empty_parameters(attributes['params'])

        return attributes

    @staticmethod
    def validate_param(param, value, valid_range=None, validity_clause=None):
        returned_value = None
        if value is not None:
            if valid_range is not None:
                validity_clause = (valid_range[0] <= value <= valid_range[-1])
            if validity_clause:
                returned_value = value
            else:
                raise_value_error(
                    param=param,
                    value=str(value),
                    subpage="tutorial-startLteUplinkCCMTest.html")

        return returned_value

    @staticmethod
    def filter_empty_parameters(params):
        return {k: v for k, v in params.items() if v is not None}
